def head(title): return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,500;6..72,600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"><style>{CSS}</style></head><body><main>'''
def foot(): return '</main></body></html>'
def svg(nodes,edges):
    parts=['<svg viewBox="0 0 760 150" role="img" aria-label="Signal map">','<defs><marker id="arr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6 z" fill="#94a3b8"/></marker></defs>']
    for x,y,w,h,label,color in nodes:
        xf,yf,wf,hf=map(float,(x,y,w,h)); parts += [f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="7" fill="{color}" stroke="#cbd5e1"/><text x="{xf+wf/2}" y="{yf+27}" text-anchor="middle" class="label">{escape(label)}</text>']
    for x1,y1,x2,y2,red in edges: parts.append(f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{"#b3261e" if red else "#94a3b8"}" stroke-dasharray="{"5 4" if red else "0"}" marker-end="url(#arr)"/>')
    return '<div class="diagram">'+''.join(parts)+'</svg></div>'

