def lane_html(l):
    cards=''
    for title,url,kind,what,use,caveat,action in l['items']:
        cards+=f'''<article class="card"><div class="badges"><span class="badge good">{escape(kind)}</span><span class="badge">fresh signal</span></div><h2>{escape(title)}</h2><ul class="facts"><li>source: {escape(url)}</li><li>published / updated: 2026-08-11</li></ul><h3>What it is</h3><p>{escape(what)}</p><h3>Buildn / client use</h3><p>{escape(use)}</p><h3>Why useful now</h3><p>{escape(action)}</p><div class="callout"><strong>Caveat:</strong> {escape(caveat)}</div></article>'''
    return head(f'Daily Ingest Dossier — {l["title"]}')+f'''<header>{logo()}<h1>Daily Ingest Dossier — {escape(l['title'])}</h1><div class="date">{DATE} · adaptive lane</div><p class="readout">{escape(l['readout'])}</p><p><a href="index.html">← today’s overview</a></p></header><section><article class="card"><h2>Signal map</h2>{svg(l['nodes'],l['edges'])}<p>{escape(l['rationale'])}</p></article>{cards}<article class="card"><h2>Use-case matrix</h2><table class="matrix"><tr><th>Theme</th><th>Buildn OS</th><th>Client work</th><th>Agent workflows</th><th>Personal leverage</th></tr><tr><td>Control surface</td><td>Budget and review evidence</td><td>Measured rollout</td><td>Explicit permissions</td><td>Repeatable defaults</td></tr><tr><td>First experiment</td><td>Instrument one path</td><td>Replay one workflow</td><td>Set a rollback</td><td>Keep a short log</td></tr></table></article><article class="card"><h2>Top actions</h2><ol class="wins"><li>{escape(l['items'][0][6])}</li><li>{escape(l['items'][1][6])}</li><li>Capture the result as a dated artifact.</li></ol></article><article class="card"><h2>Source trail</h2><ol class="source-trail">{''.join(f'<li><a href="{escape(x[1])}">{escape(x[0])}</a></li>' for x in l['items'])}</ol></article></section>{foot()}'''

